export const beats=duration=>({beats:Array.from({length:6},(_,i)=>({id:`beat-${i+1}`,label:['Hook','Context','Development','Evidence','Payoff','Closing'][i],expectedMeaning:'Test narration meaning',subjects:[],requiredEvidence:[],start:duration*i/6,end:duration*(i+1)/6,importance:'medium'}))});
export const plan=(duration=1)=>({...beats(duration),shotPlan:[{sectionIndex:0,shotId:'shot-a',order:0,sourceStart:0,sourceEnd:1,speed:1,camera:'wide',transition:'cut',rationale:'Test representative frame'}],payoff:'Test closing moment.',validationChecklist:['Review test evidence.']});
export const audit=()=>({verdict:'PASS',scores:{storyAccuracy:85,visualSupport:85,captionAccuracy:85,pacing:85,overall:85},reconstructedStory:'Test narration and rendered picture.',segments:[],issues:[],solutionPlan:{},revisedTimeline:[],validationChecklist:[],limitations:['Sparse frame sampling.']});
export const model=(extra={})=>({id:'test/vision:free',name:'Test vision',architecture:{input_modalities:['text','image'],output_modalities:['text']},pricing:{prompt:'0',completion:'0',image:'0',request:'0'},supported_parameters:['structured_outputs'],...extra});
