export const reply=(data,extra={})=>({id:'test-request',model:'test/vision:free',provider:'test-double',usage:{prompt_tokens:10,completion_tokens:20,total_tokens:30},choices:[{finish_reason:'stop',message:{content:JSON.stringify(data)}}],...extra});
